exercises.solution:
def safe_average(values):
    total = 0
    count = 0
    for v in values:
        try:
            total += float(v)
            count += 1
        except ValueError:
            pass
    if count == 0:
        return 0
    return total / count

books = input().split(",")
n = int(input())
available = {}
for book in books:
    available[book] = True
for _ in range(n):
    line = input()
    cmd, _, title = line.partition(" ")
    if cmd == "대출":
        if title not in available:
            print(f"없는 책: {title}")
        elif not available[title]:
            print(f"이미 대출 중: {title}")
        else:
            available[title] = False
            print(f"대출 완료: {title}")
    elif cmd == "반납":
        if available.get(title, True):
            print(f"대출 기록 없음: {title}")
        else:
            available[title] = True
            print(f"반납 완료: {title}")
    elif cmd == "목록":
        free = []
        for book in sorted(available):
            if available[book]:
                free.append(book)
        if free:
            print("대출 가능: " + ", ".join(free))
        else:
            print("대출 가능: 없음")
    else:
        print(f"알 수 없는 명령: {line}")

